style.css:
@-moz-document domain("roblox.com") {
/* Background image */
  body, html {
    background: url("https://i.imgur.com/7oRxZ2g.png") no-repeat center center fixed !important;
    background-size: cover !important;
    color: #ffffff !important;
    font-family: 'Courier New', monospace !important;
  }

  /* Overlay to improve contrast */
  body::before {
    content: "";
    position: fixed;
    top: 0; left: 0; right: 0; bottom: 0;
    background: rgba(0, 0, 0, 0.5);
    z-index: -1;
  }

  /* Top Navbar */
  .navigation-container, .rbx-header, .header, #header {
    background-color: rgba(25, 0, 50, 0.8) !important;
    border-bottom: 2px solid #ff8ae2 !important;
  }

  /* Main content boxes */
  .container-main, .content, .section, .card-item, .game-card, .game-card-container {
    background-color: rgba(0, 0, 0, 0.6) !important;
    border: 1px solid #ffa3c1 !important;
    border-radius: 12px !important;
    padding: 10px !important;
    color: #fff !important;
  }

  /* Buttons */
  .btn-primary, .btn-control, button, .btn-secondary {
    background-color: #ff8ae2 !important;
    color: #000 !important;
    border-radius: 6px !important;
    border: none !important;
    transition: 0.3s ease all !important;
  }

  .btn-primary:hover, .btn-control:hover {
    background-color: #d185ff !important;
    color: #fff !important;
  }

  /* Links */
  a {
    color: #e1d2ff !important;
    text-shadow: 0 0 4px #ff7be9;
  }

  /* Hide ads */
  .abp, .ad, .ads-container, .sponsored, .ads {
    display: none !important;
  }

  /* Custom Scrollbar */
  ::-webkit-scrollbar {
    width: 10px;
  }
  ::-webkit-scrollbar-thumb {
    background: #ff7be9;
    border-radius: 10px;
  }
  ::-webkit-scrollbar-track {
    background: #1f1f3b;
  }
}
